body:
I made some suggestions on top of your changes:

1. Added a missing case for binary notation (`0b` or `0B`).
2. Moved the check to the analyzer so that the precedence is properly taken into account (the difference between `-9223372036854775808` and `-9223372036854775808**2`, the later should print a representation error). I'd like to resolve this in the parser, but the lack of a context system makes it problematic.

<details>
<summary>Patch</summary>

```diff
diff --git a/modules/gdscript/gdscript_analyzer.cpp b/modules/gdscript/gdscript_analyzer.cpp
index 801776763c..80794c62c8 100644
--- a/modules/gdscript/gdscript_analyzer.cpp
+++ b/modules/gdscript/gdscript_analyzer.cpp
@@ -4689,11 +4689,16 @@ void GDScriptAnalyzer::reduce_lambda(GDScriptParser::LambdaNode *p_lambda) {
 	pending_body_resolution_lambdas.push_back(p_lambda);
 }

-void GDScriptAnalyzer::reduce_literal(GDScriptParser::LiteralNode *p_literal) {
+void GDScriptAnalyzer::reduce_literal(GDScriptParser::LiteralNode *p_literal, bool p_is_unary_negation) {
 	p_literal->reduced_value = p_literal->value;
 	p_literal->is_constant = true;

 	p_literal->set_datatype(type_from_variant(p_literal->reduced_value, p_literal));
+
+	if (p_literal->is_overflowed_by_one && !p_is_unary_negation) {
+		// Replicate the behavior of regular overflowed literals. They don't produce a syntax error, but only print an error.
+		print_error(vformat("Cannot represent %s as a 64-bit signed integer, since the value is too large.", p_literal->source.remove_char('_')));
+	}
 }

 void GDScriptAnalyzer::reduce_preload(GDScriptParser::PreloadNode *p_preload) {
@@ -5220,8 +5225,6 @@ void GDScriptAnalyzer::reduce_type_test(GDScriptParser::TypeTestNode *p_type_tes
 }

 void GDScriptAnalyzer::reduce_unary_op(GDScriptParser::UnaryOpNode *p_unary_op) {
-	reduce_expression(p_unary_op->operand);
-
 	GDScriptParser::DataType result;

 	if (p_unary_op->operand == nullptr) {
@@ -5230,6 +5233,13 @@ void GDScriptAnalyzer::reduce_unary_op(GDScriptParser::UnaryOpNode *p_unary_op)
 		return;
 	}

+	if (p_unary_op->variant_op == Variant::OP_NEGATE && p_unary_op->operand->type == GDScriptParser::Node::LITERAL) {
+		// Ignore `is_overflowed_by_one` since negating `INT64_MIN` will result in itself.
+		reduce_literal(static_cast<GDScriptParser::LiteralNode *>(p_unary_op->operand), true);
+	} else {
+		reduce_expression(p_unary_op->operand);
+	}
+
 	GDScriptParser::DataType operand_type = p_unary_op->operand->get_datatype();

 	if (p_unary_op->operand->is_constant) {
